<template>
  <div class="row">
    <div class="col-6 text-white text-uppercase title q-ml-auto text-right">
      Next Model Training update:
    </div>
    <div
      class="col-4 training-timer secondary-c-text next_model_training_time"
      style="width: 150px"
    ></div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import Clock from 'src/pages/Settings/Components/flipCardCounter/counter';

export default defineComponent({
  el: '#app',
  props: {},
  watch: {
    next_model_training_time: {
      handler: function (newVal, oldVal) {
        this.setCounter();
      },
    },
  },
  mounted() {
    this.initView();
  },
  methods: {
    async initView() {
      this.next_model_training_time = await this.getNextModelTrainingTime();
      this.setCounter();
    },

    makeCounter() {
      let mainEl = document.querySelector(
        '.next_model_training_time',
      ) as HTMLElement;

      mainEl.innerHTML = '';
      var deadline = new Date(this.counter_dateTime);
      // var deadline = new Date('Jan 5, 2022 15:37:25');
      var c = new Clock(deadline);

      mainEl.appendChild(c.el);
      return;
    },

    getDistance() {
      const now = new Date().getTime();
      // Find the distance between now and the count down date
      const distance = this.counter_time - now;
      return distance;
    },

    setCounter() {
      try {
        if (!this.next_model_training_time) {
          return;
        }
        this.counter_dateTime = new Date(this.next_model_training_time);
        this.counter_time = this.counter_dateTime.getTime();
        const distance = this.getDistance();

        if (distance < 0) {
          this.expired_tries++;
          // check for next time
          // check the next schedule time and call api
          //  this.getNextModelTrainingTime();
        }
        this.makeCounter();
      } catch (err) {
      } finally {
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { getNextModelTrainingTime } = settings_store;

    const { loading_next_model_training_time, next_model_training_time } =
      storeToRefs(settings_store);
    return {
      getNextModelTrainingTime,
      loading_next_model_training_time,
      next_model_training_time,
      counter_value: ref(''),
      counter_time: ref(0),
      counter_dateTime: ref({} as Date),
      counter_interval: ref(0 as any),
      expired_tries: ref(0),
    };
  },
});
</script>
