<!--vbase-->
<template>
  <!-- Regex List -->
  <q-dialog
    v-model="display_list"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="display_list = false"
  >
    <q-card style="width: 1000px; max-width: 1060px; height: 600px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('manage_regexes') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" @click="checkForUnSaveChanges()" />
      </q-toolbar>
      <q-card-section class="row items-center q-pb-none"> </q-card-section>

      <q-card-section>
        <div
          class="table-container col-sm-12 col-md-12 col-lg-12 min-height-300"
        >
          <q-table
            ref="tableRef"
            style="height: 500px"
            :class="'sticky-header-table table-regexex-' + doctype"
            table-header-class="back-white"
            :rows="rows"
            :no-data-label="$t('no_record_found')"
            :columns="columns as any"
            :rows-per-page-options="[0]"
            row-key="id"
            :filter="filter"
            :loading="loading"
            :filter-method="customFilter"
          >
            <template v-slot:top>
              <q-input
                outlined
                debounce="300"
                dense
                color="primary"
                v-model="filter"
                :label="$t('search')"
              >
                <template v-slot:append>
                  <q-icon name="search" />
                </template>
              </q-input>
              <q-space />
              <q-btn
                color="primary"
                class="mr-6"
                style="height: 40px"
                :label="$t('add_new')"
                @click="addNew()"
              />
              <q-btn
                v-if="validate_pattern === true"
                color="orange"
                class="mr-6"
                style="height: 40px"
                :label="$t('validate')"
                @click="validatePattern()"
              />
              <q-btn
                v-if="hasPendingUpdate()"
                color="red"
                class="mr-6"
                style="height: 40px"
                :label="$t('save_changes')"
                @click="saveAll()"
              />
            </template>

            <template v-slot:body="props">
              <q-tr
                :props="props"
                :id="props.key"
                v-if="props.row.is_deleted === false"
              >
                <template
                  v-for="col in props.cols"
                  :key="col.name"
                  :props="props"
                >
                  <q-td v-if="col.name === 'action'" style="width: 10%">
                    <template v-if="props.row.id !== ''">
                      <span class="q-ml-auto">
                        <q-btn
                          :color="
                            props.row.disabled === false
                              ? 'positive'
                              : 'negative'
                          "
                          :icon-right="
                            props.row.disabled === false
                              ? 'visibility'
                              : 'visibility_off'
                          "
                          no-caps
                          flat
                          dense
                          @click="handleDisable(props.row, props.rowIndex)"
                        >
                          <q-tooltip>
                            <template v-if="props.row.org_id !== DEFAULT_ORG_UUID">
                              {{
                                props.row.disabled === false
                                  ? $t('click_to_disable')
                                  : $t('click_to_enable')
                              }}
                            </template>
                            <template v-else>
                              {{ $t('cannot_edit_default_type') }}
                            </template>
                          </q-tooltip>
                        </q-btn>

                        <q-btn
                          v-if="props.row.org_id !== DEFAULT_ORG_UUID"
                          color="grey"
                          icon-right="delete"
                          no-caps
                          flat
                          dense
                          @click="handleDelete(props.row, props.rowIndex)"
                        >
                          <q-tooltip>{{ $t('delete') }}</q-tooltip>
                        </q-btn>
                      </span>
                    </template>

                    <template v-if="props.row.id === ''">
                      <q-btn
                        class="float-right"
                        color="grey"
                        icon-right="delete"
                        no-caps
                        flat
                        dense
                        @click="deleteNewRow(props.rowIndex)"
                      >
                        <q-tooltip>{{ $t('delete') }}</q-tooltip>
                      </q-btn>
                    </template>
                  </q-td>

                  <q-td
                    v-if="col.name === 'regexValuePattern'"
                    style="width: 70%"
                  >
                    <q-input
                      borderless
                      tabindex="0"
                      :data-id="props.key"
                      :class="
                        'input-field ' +
                        (!props.row.validate || props.row.required_error
                          ? 'column-error-border'
                          : '')
                      "
                      v-model="props.row.regexValuePattern"
                      :disable="props.row.org_id == DEFAULT_ORG_UUID ? true : false"
                      @update:model-value="
                        (val: any) => {
                          inputValueChanges(
                            'regexValuePattern',
                            props.key,
                            val,
                            props.rowIndex,
                          );
                        }
                      "
                    >
                      <template v-slot:append>
                        <q-icon
                          v-if="!props.row.validate || props.row.required_error"
                          flat
                          dense
                          name="error"
                          size="24px"
                          color="red"
                        >
                          <q-tooltip class="bg-red line-error-tooltip">
                            <template v-if="!props.row.validate">
                              {{ $t('pattern_invalid') }}
                            </template>
                            <template v-if="props.row.required_error">
                              {{ $t('pattern_empty') }}
                            </template>
                          </q-tooltip>
                        </q-icon>
                      </template>

                      <q-tooltip
                        v-if="props.row.org_id == DEFAULT_ORG_UUID"
                        class="bg-red"
                      >
                        {{ $t('cannot_edit_default_type') }}
                      </q-tooltip>
                    </q-input>
                  </q-td>

                  <q-td v-if="col.name === 'regexOrigin'" style="width: 20%">
                    <q-select
                      borderless
                      tabindex="0"
                      :data-id="props.key"
                      v-model="props.row.regexOrigin"
                      :options="language_origin_list"
                      :disable="props.row.org_id == DEFAULT_ORG_UUID ? true : false"
                      @update:model-value="
                        (val: any) => {
                          inputValueChanges(
                            'regexOrigin',
                            props.key,
                            val,
                            props.rowIndex,
                          );
                        }
                      "
                      emit-value
                      map-options
                    >
                      <q-tooltip
                        v-if="props.row.org_id == DEFAULT_ORG_UUID"
                        class="bg-red"
                      >
                        {{ $t('cannot_edit_default_type') }}
                      </q-tooltip>
                    </q-select>
                  </q-td>
                </template>
              </q-tr>
            </template>
          </q-table>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- END Regex List -->

  <!-- Un Save Changes Warning -->
  <q-dialog
    v-model="unsave_warning"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('unsave_changes_warning') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="unsave_warning = false"
        />
        <f-btn
          data-cy="done"
          :label="$t('proceed')"
          @click="proceedWithOutSave()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Un Save Changes Warning -->
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken, getRegexSaveUrl } from 'pages/APIs';
import axios from 'axios';
import type { dynamicObj } from 'src/pages/assets';
import { isObjectEmtpy } from 'src/utils/general';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { notify } from 'src/components/notifications/notify';
import {
  getOrgId,
  addOrgIdQueryString,
} from 'src/utils/organization/org_id_helper';
import { DEFAULT_ORG_UUID } from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    type: {
      type: String,
      default: 'document',
    },
    loading_new_data: {
      type: Boolean,
      default: false,
    },
    doctype: {
      type: String,
      default: '',
    },
    display: {
      type: Boolean,
      default: false,
    },
    list_data: {} as any,
    language_origin_list: {
      type: Array,
      default: () => [],
    },
  },
  components: {},
  data() {
    return {
      docId: '',
    };
  },
  setup() {
    let data: any = [];
    const columns = ref(data);
    return {
      display_list: ref(false),
      loading: ref(true),
      columns,
      rows: ref(data),
      filter: ref(''),
      pending_update: ref({} as { [k: string]: any }),
      original_data: {} as any,
      unsave_warning: ref(false),
      validate_pattern: ref(false),
      flat_language_list: ref({} as { [k: string]: any }),
      DEFAULT_ORG_UUID,
    };
  },
  watch: {
    loading_new_data: {
      handler: function (newVal, oldVal) {
        if (newVal === true) {
          this.loading = newVal;
        }
      },
    },
    display: {
      handler: function (newVal, oldVal) {
        if (newVal === true) {
          this.display_list = newVal;
          this.loading = !newVal;
          this.prepareListView(this.list_data);
        }
      },
    },
    list_data: {
      handler: function (newVal, oldVal) {
        this.prepareListView(newVal);
        this.flatLanguageList();
      },
    },
  },
  mounted: function () {
    this.docId = this.$route.params.id as string;
    this.prepareColumns();
  },
  methods: {
    flatLanguageList() {
      // flat_language_list
      if (!isObjectEmtpy(this.flat_language_list)) {
        return;
      }

      for (let [key, value] of Object.entries(this.language_origin_list)) {
        let val = value as any;
        this.flat_language_list[val.value] = val.label;
      }
    },

    showListView() {
      this.display_list = true;
    },
    prepareListView(data: any) {
      this.original_data = JSON.parse(JSON.stringify(data));
      this.prepareRows();
    },
    prepareColumns() {
      this.columns.push(
        Object.assign(
          {},
          {
            name: 'regexOrigin',
            label: this.$t('origin'),
            field: 'regexOrigin',
            align: 'left',
          },
        ),
      );
      this.columns.push(
        Object.assign(
          {},
          {
            name: 'regexValuePattern',
            label: this.$t('pattern'),
            field: 'regexValuePattern',
            align: 'left',
          },
        ),
      );
      this.columns.push(
        Object.assign(
          {},
          {
            name: 'action',
            label: this.$t('action'),
            field: 'action',
            align: 'right',
          },
        ),
      );
    },
    prepareRows() {
      this.rows = [] as any;
      for (let [index, item] of Object.entries(this.list_data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },
    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      newRow['validate'] = true;
      newRow['required_error'] = false;
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },
    addNew() {
      const current_index = this.addNewRow({
        id: '',
        regexType: this.doctype,
        regexValuePattern: '',
        regexOrigin: '',
        is_deleted: false,
        org_id: getUserDetailFromkey('org_id'),
      } as dynamicObj);

      this.pending_update[current_index] = true;
      setTimeout(() => {
        this.scrollToBottom();
      }, 0);
    },
    scrollToBottom() {
      let element = document.querySelector('.table-regexex-' + this.doctype);
      if (!element) {
        return;
      }

      let table_middle = element.querySelector('.q-table__middle');
      if (!table_middle) {
        return;
      }

      table_middle.scrollTop = table_middle.scrollHeight;
    },
    handleDisable(row: any, index: number) {
      try {
        if (row.id === '' || row.org_id == DEFAULT_ORG_UUID) {
          return;
        }
        this.rows[index].disabled = !row.disabled;
        this.pending_update[index.toString()] = true;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
    handleDelete(row: any, index: number) {
      try {
        if (row.id === '') {
          return;
        }
        this.rows[index].is_deleted = true;

        this.pending_update[index.toString()] = true;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    deleteNewRow(index: number) {
      this.rows.splice(index, 1);

      const current_index = index.toString();
      if (this.pending_update.hasOwnProperty(current_index)) {
        delete this.pending_update[current_index];
      }
    },
    inputValueChanges(
      column_name: string,
      rowId: string,
      new_val: any,
      index: number,
    ) {
      if (
        rowId === '' &&
        column_name == 'regexValuePattern' &&
        new_val !== ''
      ) {
        this.validate_pattern = true;
        return;
      }
      for (let [index, item] of Object.entries(this.original_data)) {
        const row = item as dynamicObj;

        if (rowId !== row.id) {
          continue;
        }
        if (row[column_name] === new_val) {
          continue;
        }

        if (column_name == 'regexValuePattern' && new_val !== '') {
          this.validate_pattern = true;
          continue;
        }
        this.pending_update[index.toString()] = true;
      }
    },
    async saveAll() {
      try {
        if (!this.validateData()) {
          return;
        }
        this.cleanUpDataBeforeSave();
        this.showLoading();
        let response: any;
        let token: string = await getAuthorizationToken();

        let formData = new FormData();
        formData.append('data', JSON.stringify(this.rows));
        formData.append('org_id', getOrgId());
        response = await axios.post(
          api.post_data_fellowkv + getRegexSaveUrl(this.type),
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw { message: response.data.message };
        }
        this.pending_update = {};
        this.dispatchSuccessEvent();
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
        this.hideLoading();
      }
    },
    validateData() {
      let has_error = true;
      if (this.validate_pattern) {
        has_error = false;
        notify.error('Please validate Before save.');
      }
      if (this.regexValuePatternsEmpty()) {
        has_error = false;
        notify.error('Pattern field is required');
      }

      return has_error;
    },
    regexValuePatternsEmpty() {
      let has_empty = false;
      this.rows.forEach((row: any, index: any) => {
        if (!row['regexValuePattern'] || row['regexValuePattern'] === '') {
          row.required_error = true;
          has_empty = true;
        } else {
          row.required_error = false;
        }
      });
      return has_empty;
    },
    cleanUpDataBeforeSave() {
      this.rows.forEach((row: any, index: any) => {
        if (!row['id'] || row['id'] === '') {
          delete row['id'];
        }
      });
    },
    dispatchSuccessEvent() {
      const event = new CustomEvent('regexes_saved', { detail: this.doctype });
      document.dispatchEvent(event);
    },
    checkForUnSaveChanges() {
      if (this.hasPendingUpdate()) {
        this.unsave_warning = true;
        return;
      }
      this.display_list = false;
    },
    hasPendingUpdate() {
      return !isObjectEmtpy(this.pending_update);
    },
    proceedWithOutSave() {
      this.unsave_warning = false;
      this.display_list = false;
      this.pending_update = {};
      this.validate_pattern = false;
    },
    async validatePattern() {
      try {
        if (this.regexValuePatternsEmpty()) {
          notify.error('Pattern field is required');
          return;
        }
        this.showLoading();
        let response: any;
        let token: string = await getAuthorizationToken();

        let formData = new FormData();
        formData.append(
          'patterns',
          JSON.stringify(this.getValidatePatternData()),
        );
        formData.append('org_id', getOrgId());
        response = await axios.post(api.validate_patterns, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw { message: response.data.message };
        }
        this.validate_pattern = false;
        this.updateRows(response.data.data);
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
        this.hideLoading();
      }
    },
    updateRows(result: any) {
      for (let [pattern, validate] of Object.entries(result)) {
        this.rows.forEach((row: any, index: any) => {
          if (row['regexValuePattern'] == pattern) {
            const new_validate = validate === false ? false : true;
            row.validate = new_validate;
            if (new_validate === false) {
              this.pending_update[index.toString()] = true;
              this.validate_pattern = true;
            }
          }
        });
      }
    },
    getValidatePatternData() {
      let regexes = [] as string[];
      this.rows.forEach((row: any, index: any) => {
        const regex =
          !row['regexValuePattern'] || row['regexValuePattern'] === ''
            ? ''
            : row['regexValuePattern'].toString();
        regexes.push(regex);
      });

      return regexes;
    },
    customFilter(
      rows: readonly any[],
      terms: any,
      cols?: readonly any[],
      getCellValue?: (col: any, row: any) => any,
    ): readonly any[] {
      const lowerSearch = terms.toLowerCase();
      let filteredRows: readonly any[] = rows;
      if (!lowerSearch || lowerSearch === '') {
        return filteredRows;
      }

      filteredRows = rows.filter((row: any, i: number) => {
        let found = false;
        for (let [key, value] of Object.entries(row)) {
          let val = value as any;
          let original_val = val && val !== null ? val.toString() : '';
          val = original_val.toLowerCase();

          if (val.includes(lowerSearch)) {
            found = true;
            break;
          }

          // dropdown
          if (
            key === 'regexOrigin' &&
            val &&
            this.flat_language_list[original_val]
          ) {
            val = this.flat_language_list[original_val].toLowerCase();
            if (val.includes(lowerSearch)) {
              found = true;
              break;
            }
          }
        }

        return found;
      });

      return filteredRows;
    },
  },
});
</script>

<style lang="scss" scoped>
.column-error-border {
  border: 1px solid red;
}
</style>
<style lang="scss">
